import{_ as a,c as s,o as n,aj as r}from"./chunks/framework.CMWtagCP.js";const g=JSON.parse('{"title":"2025-03-31-Shardingsphere-prometheus-配置","description":"","frontmatter":{"title":"2025-03-31-Shardingsphere-prometheus-配置","hugoSource":"blog/2025/2025-03-31-Shardingsphere-prometheus-配置.md","outline":[1,6]},"headers":[],"relativePath":"article/2025/2026-11-17-2025-03-31-Shardingsphere-prometheus-配置.md","filePath":"article/2025/2026-11-17-2025-03-31-Shardingsphere-prometheus-配置.md"}'),p={name:"article/2025/2026-11-17-2025-03-31-Shardingsphere-prometheus-配置.md"};function i(t,e,l,o,h,c){return n(),s("div",null,[...e[0]||(e[0]=[r(`<h1 id="_2025-03-31-shardingsphere-prometheus-配置" tabindex="-1">2025-03-31-Shardingsphere-prometheus-配置 <a class="header-anchor" href="#_2025-03-31-shardingsphere-prometheus-配置" aria-label="Permalink to “2025-03-31-Shardingsphere-prometheus-配置”">​</a></h1><p>把 shardingsphere proxy 搭建好之后，想要把监测数据放到 grafana里面进行监测，但是按照找到的资料来配置好像都不太行，自己研究了一下启动脚本，现在可以正常获取到指标数据了，所以花点时间把这个问题记录一下</p><p>下载了官网提供的 shardingsphere-proxy 的包之后，里面其实已经包含了 agent 相关的 jar 包以及插件相关的 jar 包，其实不需要再下载一个 shardingsphere-agent</p><p>我们需要配置一下<code>agent.yaml</code>里面的内容，文件的位置在 <code>apache-shardingsphere-5.5.2-shardingsphere-proxy-bin/agent/conf/agent.yaml</code>，现在只需要配置 prometheus，所以如下所示</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>plugins:</span></span>
<span class="line"><span>  metrics:</span></span>
<span class="line"><span>    Prometheus:</span></span>
<span class="line"><span>      host: &quot;localhost&quot;</span></span>
<span class="line"><span>      port: 9000</span></span>
<span class="line"><span>      props:</span></span>
<span class="line"><span>        jvm-information-collector-enabled: &quot;true&quot;</span></span></code></pre></div><p>在 prometheus 的配置文件中需要加上 9000 的指标接口（如果是使用 brew 安装的话，配置文件在这个位置 <code>/opt/homebrew/etc/prometheus.yml</code>）</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>scrape_configs:</span></span>
<span class="line"><span>  - job_name: &#39;shardingsphere&#39;</span></span>
<span class="line"><span>    static_configs:</span></span>
<span class="line"><span>      - targets: [&#39;localhost:9000&#39;]</span></span></code></pre></div><p>网上查到的这篇文章 <a href="https://xie.infoq.cn/article/37c5c2380ce7f3c495b6841c7" target="_blank" rel="noreferrer">Apache ShardingSphere Agent 可观察性实用指南</a> 提到需要修改脚本文件，其实是不用修改的，只需要夹一个参数 <code>--agent</code> 就可以</p><p>需要注意的是运行的目录需要在 shardingsphere-proxy 的根目录下，因此命令如下所示</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sh bin/start.sh 5555 --agent</span></span></code></pre></div><p>查看日志 <code>vim logs/stdout.log</code> 打印的应该如下所示</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Mar 31, 2025 6:07:37 PM org.apache.shardingsphere.agent.core.plugin.jar.PluginJarLoader load</span></span>
<span class="line"><span>INFO: Loaded jar: shardingsphere-agent-metrics-prometheus-5.5.2.jar</span></span>
<span class="line"><span>Mar 31, 2025 6:07:37 PM org.apache.shardingsphere.agent.core.plugin.jar.PluginJarLoader load</span></span>
<span class="line"><span>INFO: Loaded jar: shardingsphere-agent-tracing-opentelemetry-5.5.2.jar</span></span>
<span class="line"><span>Mar 31, 2025 6:07:37 PM org.apache.shardingsphere.agent.core.plugin.jar.PluginJarLoader load</span></span>
<span class="line"><span>INFO: Loaded jar: shardingsphere-agent-metrics-core-5.5.2.jar</span></span>
<span class="line"><span>Mar 31, 2025 6:07:37 PM org.apache.shardingsphere.agent.core.plugin.jar.PluginJarLoader load</span></span>
<span class="line"><span>INFO: Loaded jar: shardingsphere-agent-plugin-core-5.5.2.jar</span></span>
<span class="line"><span>Mar 31, 2025 6:07:37 PM org.apache.shardingsphere.agent.core.plugin.jar.PluginJarLoader load</span></span>
<span class="line"><span>INFO: Loaded jar: shardingsphere-agent-logging-file-5.5.2.jar</span></span>
<span class="line"><span>[INFO ] 2025-03-31 18:07:38.772 [main] o.a.s.d.p.c.l.PipelineContextManagerLifecycleListener - mode type is not Cluster, mode type=&#39;Standalone&#39;, ignore</span></span>
<span class="line"><span>[INFO ] 2025-03-31 18:07:38.786 [main] o.a.s.p.v.ShardingSphereProxyVersion - Database type is \`MySQL\`, version is \`8.0.41\`, database name is \`sharding_db\`</span></span>
<span class="line"><span>[INFO ] 2025-03-31 18:07:38.786 [main] o.a.s.p.frontend.ssl.ProxySSLContext - Proxy frontend SSL/TLS is not enabled.</span></span>
<span class="line"><span>[INFO ] 2025-03-31 18:07:38.836 [main] o.a.s.p.frontend.ShardingSphereProxy - ShardingSphere-Proxy Standalone mode started successfully</span></span></code></pre></div><p>这个时候需要查询一下数据库，agent才会把服务启起来</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[INFO ] 2025-03-31 18:08:14.258 [nioEventLoopGroup-3-1] o.a.s.a.c.p.PluginLifecycleServiceManager - Start plugin: Prometheus</span></span>
<span class="line"><span>[INFO ] 2025-03-31 18:08:14.290 [nioEventLoopGroup-3-1] o.a.s.a.p.m.p.PrometheusPluginLifecycleService - Prometheus metrics HTTP server \`localhost:9000\` start success.</span></span></code></pre></div><p>日志如上打印之后，agent就真正启动了。访问 <code>http://localhost:9000/metrics</code> 可以看到返回了指标数据</p><h2 id="reference" tabindex="-1">Reference <a class="header-anchor" href="#reference" aria-label="Permalink to “Reference”">​</a></h2><ul><li><a href="https://shardingsphere.apache.org/document/current/cn/user-manual/shardingsphere-proxy/observability/" target="_blank" rel="noreferrer">可观察性的使用</a><ul><li>官方文档</li></ul></li><li><a href="https://xie.infoq.cn/article/37c5c2380ce7f3c495b6841c7" target="_blank" rel="noreferrer">Apache ShardingSphere Agent 可观察性实用指南</a></li></ul>`,17)])])}const u=a(p,[["render",i]]);export{g as __pageData,u as default};
